import{_ as n,l,o as e,c as o,v as t,p as s,x as i,d as m,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Pin risk","description":"","frontmatter":{"title":"Pin risk","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pin-risk.md","filePath":"quant/pin-risk.md","lastUpdated":1789023840000}'),d={name:"quant/pin-risk.md"};function u(E,a,c,D,B,A){const r=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="pin-risk" tabindex="-1">Pin risk <a class="header-anchor" href="#pin-risk" aria-label="Permalink to &quot;Pin risk&quot;">​</a></h1><div class="epigraph"><p>到期日若现货收在执行价附近，期权空头的 Gamma 在最后一段时间内爆炸，对冲方向取决于收盘落在行权还是不行权一侧——这一不确定性无法用盘中 Delta 限额消去。</p><footer>—— 到期钉住的经验见 Ni, Pearson and Poteshman, Journal of Financial Economics, 2005；对冲叙述见期权做市实务与 Hull</footer></div><p>到期日临近，平值期权的 \\(\\Gamma\\sim 1/(S\\sigma\\sqrt{\\tau})\\) 随剩余时间 \\(\\tau\\to 0\\) 发散。若标的停在执行价 \\(K\\) 附近，做市商的对冲头寸必须在「全额交割标的」与「零交割」之间跳。哪一侧发生，取决于最后价格相对 \\(K\\) 的一tick。这种因行权阈值造成的缺口，叫做 <strong>pin risk</strong>（钉住风险）。它与微观结构里的 <a href="/quant/pin">信息交易概率 PIN</a> 同名不同物：PIN 是知情交易强度的日度估计，pin risk 是期权到期的机械风险。经验上，到期日现货收在最大未平仓执行价附近的频率偏高，Ni、Pearson 与 Poteshman（2005）把这一「钉住」写成可检验的现象。本篇写对冲与 Gamma 爆炸，衔接 <a href="/quant/greeks-hedge">希腊字母</a> 与 <a href="/quant/delta-hedge-freq">对冲频率</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设做市商卖出执行价 \\(K\\) 的看涨，Delta 对冲持有 \\(\\Delta\\) 份标的。\\(\\tau\\) 较大时 \\(\\Delta\\) 在 \\(0\\) 与 \\(1\\) 之间光滑移动。\\(\\tau\\) 极小时，路径若在 \\(K\\) 附近游荡，\\(\\Delta\\) 在 \\(0\\) 与 \\(1\\) 之间剧烈摇摆，每摆一次都要交易接近一份标的。收盘若钉在 \\(K\\)，行权与否可能拖到截止时间之后才确认，隔夜持有未知的 Delta。即使最终「精确钉住」使期权毫无价值且未行权，盘中为了对冲已经付出巨大换手；若钉偏一tick 导致全部行权，隔夜缺口等于一整份现货。</p><p>问题是三重的：盘中 Gamma 爆炸的复制误差、截止时刻的二元不确定性、以及未平仓本身可能把现货「吸」向 \\(K\\)（钉住是否为因果仍有争议）。对冲频率理论在 \\(\\Gamma\\to\\infty\\) 时建议连续交易，但价差与可借券规模使这不可行。需要的是到期周的特殊政策，而不是把日常带宽再收一档。</p><h3 id="钉住、最大未平仓与因果" tabindex="-1">钉住、最大未平仓与因果 <a class="header-anchor" href="#钉住、最大未平仓与因果" aria-label="Permalink to &quot;钉住、最大未平仓与因果&quot;">​</a></h3><p>钉住的统计是：到期日收盘价落在最大 OI 执行价附近的概率，高于把无期权时的扩散外推所预期的。机制候选包括：对冲流在 \\(K\\) 下方买、上方卖，形成均值回复；套利者的转换与反转；以及到期相关的指数再平衡。把钉住全部写成「做市商操纵收盘」既无必要也不被一般证据支持。对风控而言，无论因果如何，只要 OI 在某一 \\(K\\) 上堆积，该点的流动性与 Gamma 就与普通交易日不同，限额必须改。</p><p><span class="marginnote">中文里 PIN 与 pin 容易混。本篇的 pin 是钉子、钉住执行价；<a href="/quant/pin">PIN</a> 是 Probability of Informed Trading。报告与代码命名应分开，避免把到期 Gamma 限额写成知情交易指标。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>到期周压缩 Gamma。</strong> 在最后数个交易日，对 \\(|\\Delta-0.5|\\) 小且 \\(\\tau\\) 短的空头，优先平仓或买回，而不是更勤地 Delta 对冲。买回消灭爆炸的 \\(\\Gamma\\)；对冲只是跟踪它。若必须留仓，用同到期邻档把净 Gamma 降下来（扁蝶或买回中间），接受 Theta 损失作为保险费。</p><p><strong>行权截止与隔夜。</strong> 明确截止时刻、自动行权阈值（价内多少）、以及通知失败的处理。在截止前把 Delta 调到「两种行权假设下损失可接受」的折中，而不是调到模型 \\(\\Delta\\)。这是对二元结果的极小极大，不是 Black–Scholes 最优复制。期货期权与股票期权的交割与借券规则不同，政策不能共用。</p><p><strong>钉住情景。</strong> 对每个大 OI 执行价，计算：收在 \\(K-\\varepsilon\\) 与 \\(K+\\varepsilon\\) 时账面 Delta 的跳、所需借券、以及指数交割结算价（特别结算 / 开盘交割）是否与连续竞价收盘不同。指数到期的 pin 发生在结算窗，不是在股票收盘铃。</p><h3 id="与离散对冲、隔夜跳空的分工" tabindex="-1">与离散对冲、隔夜跳空的分工 <a class="header-anchor" href="#与离散对冲、隔夜跳空的分工" aria-label="Permalink to &quot;与离散对冲、隔夜跳空的分工&quot;">​</a></h3><p>离散对冲误差处理的是扩散段 \\(\\frac12\\Gamma(\\Delta S)^2\\)。Pin risk 是 \\(\\tau\\to 0\\) 时 \\(\\Gamma\\) 发散，加上行权函数不连续。隔夜跳空是强制的大 \\(\\Delta t\\)。到期日三者叠加：上午仍像离散对冲，下午 Gamma 爆炸，收盘后是隔夜与行权通知。政策应按时段切换，用单一「五分钟对冲」覆盖到期日会在最后一小时换手失控。模型上，Black–Scholes 在 \\(\\tau=0\\) 的 Delta 是阶跃，任何有限频率的误差不趋于零——这与跳跃项同类，见离散误差文对跳的讨论。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Gamma 爆炸来自正态分布密度在 \\(\\sqrt{\\tau}\\to 0\\) 时向 \\(K\\) 集中：只有现货非常靠近 \\(K\\)，期权才既不是极实也不是极虚。做市商若整体空头该档，对冲流在现货上穿 \\(K\\) 时反向交易，短期像把价格往 \\(K\\) 推；若整体多头该档，对冲流强化偏离。净效应取决于行业持仓结构，不是单家台子能决定的「钉住算法」。Avellaneda 与 Lipkin 一类模型把对冲流写成价格动力学的一部分，用来解释钉住统计；风控不需要接受整套动力学，只需承认反馈可能改变最后一小时的流动性。</p><p>对冲为何失败：目标 \\(\\Delta\\) 在行权阈值两侧不连续，而可交易的是连续的现货。任何在截止前选定的 \\(\\Delta^*\\in(0,1)\\)，都会在一侧显得对冲不足、另一侧对冲过度。最优 \\(\\Delta^*\\) 取决于两侧损失的不对称（借券难、涨跌停、指数交割）。这已经超出 <a href="/quant/heston">Heston</a> 或 <a href="/quant/sabr">SABR</a> 的平滑希腊字母：那些模型在 \\(\\tau\\to 0\\) 同样给出变陡的阶跃，只是路径不同。</p><h3 id="charm-把问题提前暴露" tabindex="-1">Charm 把问题提前暴露 <a class="header-anchor" href="#charm-把问题提前暴露" aria-label="Permalink to &quot;Charm 把问题提前暴露&quot;">​</a></h3><p>Charm（\\(\\partial\\Delta/\\partial t\\)）在到期近平值处极大，意味着即使现货不动，Delta 也会因时间流逝而变。这是 <a href="/quant/higher-greeks">高阶希腊</a> 在到期周的具体用途：用 Charm 估计「下一小时若不交易、Delta 会自己走多远」，从而提前加宽或提前平仓。只看瞬时 \\(\\Delta\\) 会低估静止市场里的对冲需求。</p><p><span class="marginnote">自动行权阈值（例如价内 $0.01）把理论钉住点从 \\(K\\) 移到阈值对应的价格。风控情景应按交易所规则平移 \\(K\\)，而不是按教学上的精确 \\(S=K\\)。</span></p>',21)),(e(),s(h,null,{default:i(()=>[p(r,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20Tau%5B%22%E5%89%A9%E4%BD%99%20%CF%84%20%E2%86%92%200%22%5D%20--%5Cgt%20%20G%5B%22%E5%B9%B3%E5%80%BC%20Gamma%20%E7%88%86%E7%82%B8%22%5D%0A%20%20G%20--%5Cgt%20%20Hedge%5B%22Delta%20%E5%9C%A8%200%20%E4%B8%8E%201%20%E9%97%B4%E6%91%87%E6%91%86%22%5D%0A%20%20OI%5B%22%E5%A4%A7%20OI%20%E6%89%A7%E8%A1%8C%E4%BB%B7%22%5D%20--%5Cgt%20%20Pin%5B%22%E6%94%B6%E7%9B%98%E9%9D%A0%E8%BF%91%20K%20%E7%9A%84%E7%BB%9F%E8%AE%A1%E9%92%89%E4%BD%8F%22%5D%0A%20%20Hedge%20--%5Cgt%20%20Bin%5B%22%E8%A1%8C%E6%9D%83%20%2F%20%E4%B8%8D%E8%A1%8C%E6%9D%83%20%E4%BA%8C%E5%85%83%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20Pin%20--%5Cgt%20%20Bin%0A%20%20Bin%20--%5Cgt%20%20ON%5B%22%E9%9A%94%E5%A4%9C%E6%9C%AA%E7%9F%A5%20Delta%22%5D%0A%20%20Charm%5B%22Charm%20%E5%8D%B3%E4%BD%BF%20S%20%E4%B8%8D%E5%8A%A8%E4%B9%9F%E6%94%B9%E5%8F%98%20%CE%94%22%5D%20--%5Cgt%20%20Hedge%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不是所有到期日都有钉住。远月、虚值 OI 分散、或现货远离所有大档时，pin risk 次要。欧式指数用特别结算价，钉的是结算窗的 VWAP 或开盘，对冲工具是期货而不是股票篮子的每一只——篮子里的单名 pin 仍可能存在。美式个股在到期前即可行权，pin 被提前行权部分转移。涨跌停使 \\(\\Delta S\\) 不能连续调整，钉住与跳空分不清。</p><p>Ni–Pearson–Poteshman（2005）提供的是期权到期与价格位置的经验关系，不是保证你可以通过对冲流去「制造」收盘价。合规与交易所规则把操纵收盘排除在对冲政策之外。Heston / SABR 校准用的是未到期曲面，对 \\(\\tau\\to 0\\) 的 Gamma 峰值通常没有额外约束；不要用平常日的 Vega 限额去覆盖到期日的 Gamma。Hull 把 Gamma 列为标准风险，到期日只是这一项的极端实现。</p><p><span class="marginnote"> 用到期日实现波动去「验证」隐含波动，样本被钉住扭曲：路径在 \\(K\\) 附近被压缩，实现方差可能偏低。这是微观结构对 RV 的污染，不是微笑模型突然变准。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Pin risk 是到期日执行价附近 Gamma 爆炸与行权二元性造成的缺口风险，不是信息交易概率 PIN。</li><li>对冲频率公式在 \\(\\Gamma\\to\\infty\\) 时失效；到期周应压缩净 Gamma，而不是无限加密 Delta。</li><li>截止前的 Delta 是对两种行权结果的折中，不是光滑模型的最优复制。</li><li>大 OI 执行价改变钉住统计与流动性；指数结算窗与个股收盘不是同一事件。</li><li>Charm 显示即使现货静止，到期近平值的 Delta 也会随时间急变。</li><li>出处：Ni, Pearson and Poteshman, <em>JFE</em>, 2005；希腊字母见 Hull；离散复制见 Boyle–Emanuel，1980；对照 PIN 见 Easley et al.，1996。</li></ul>',6))])}const k=n(d,[["render",u]]);export{f as __pageData,k as default};
